{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Aprepitant, the closest structural analogue, has absolute oral bioavailability of approximately 60–65% in humans, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Brexpiprazole has about 95% absolute oral bioavailability in humans despite a polyaromatic heterocyclic structure, showing that such scaffolds can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Olaparib, containing a fluorophenyl and pyrazole/amide-like motif, has a simulated absolute oral bioavailability of 0.72, supporting high oral absorption for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Flosequinan has a mean absolute bioavailability of 72% in healthy volunteers, providing additional evidence that fluorinated heteroaromatic drugs can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Ketanserin has about 50% absolute oral bioavailability in humans, confirming that moderate-to-high F is achievable for related fluorophenyl-containing drug-like molecules.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferable experimental evidence points to oral bioavailability above the 20% threshold; no affirmative evidence of low F was found. The physicochemical prior is also favorable, though low structural similarity to the analogues limits confidence.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the query molecule.",
    "All evidence analogues have low Morgan similarity (<0.26), limiting structural transferability.",
    "Metabolic stability and first-pass extraction for the query are not experimentally characterized.",
    "Solubility and dissolution behavior are not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

